require_once __DIR__.'/../includes/auth.php';require_once __DIR__.'/../includes/parser.php';require_once __DIR__.'/../config/ai-config.php';$user=require_auth();if($_SERVER['REQUEST_METHOD']!=='POST')json_out(['error'=>'Method not allowed.'],405);
try{if(empty($_FILES['resume'])||$_FILES['resume']['error']!==UPLOAD_ERR_OK)throw new RuntimeException('Choose a resume file to analyze.');$f=$_FILES['resume'];if($f['size']>10*1024*1024)throw new RuntimeException('The file must be under 10 MB.');$ext=strtolower(pathinfo($f['name'],PATHINFO_EXTENSION));if(!in_array($ext,['pdf','docx'],true))throw new RuntimeException('Only PDF and DOCX files are supported.');$mime=(new finfo(FILEINFO_MIME_TYPE))->file($f['tmp_name']);if(!in_array($mime,['application/pdf','application/zip','application/vnd.openxmlformats-officedocument.wordprocessingml.document','application/x-zip-compressed'],true))throw new RuntimeException('The uploaded file type could not be verified.');$text=extract_resume_text($f['tmp_name'],$f['name']);$analysis=ai_json('You are a fair, evidence-based resume reviewer. Analyze only the supplied resume text. Do not infer facts. Give ATS scores from 0 to 100. Return JSON with keys overall_score, formatting_score, skills_score, experience_score, education_score, projects_score, keyword_score, grammar_score (integer); rating (string); summary (string); strengths (array of strings); weaknesses (array of strings); missing_skills (array); matched_keywords (array); missing_keywords (array); sections (object mapping Contact Information, Professional Summary, Education, Technical Skills, Work Experience, Projects, Certifications to {score: integer, feedback: string}). Be specific. If a section is absent, say so.','Analyze this resume text only:\n'.$text);
$dir=__DIR__.'/../uploads/'.$user['id'];if(!is_dir($dir)&&!mkdir($dir,0700,true))throw new RuntimeException('Unable to create secure upload folder.');$stored=bin2hex(random_bytes(20)).'.'.$ext;if(!move_uploaded_file($f['tmp_name'],$dir.'/'.$stored))throw new RuntimeException('Could not save the uploaded resume.');$pdo->beginTransaction();$q=$pdo->prepare('INSERT INTO resumes(user_id,file_name,stored_name,file_size,mime_type,extracted_text,status) VALUES(?,?,?,?,?,? ,?)');$q->execute([$user['id'],basename($f['name']),$stored,$f['size'],$mime,$text,'analyzed']);$id=(int)$pdo->lastInsertId();$pdo->prepare('INSERT INTO resume_analysis(resume_id,user_id,overall_score,formatting_score,skills_score,experience_score,education_score,projects_score,keyword_score,grammar_score,rating,report_json) VALUES(?,?,?,?,?,?,?,?,?,?,?,?)')->execute([$id,$user['id'],...array_map(fn($k)=>(int)($analysis[$k]??0),['overall_score','formatting_score','skills_score','experience_score','education_score','projects_score','keyword_score','grammar_score']),substr((string)($analysis['rating']??''),0,40),json_encode($analysis,JSON_UNESCAPED_UNICODE)]);$pdo->commit();json_out(['id'=>$id]);}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();if(isset($dir,$stored)&&is_file($dir.'/'.$stored))@unlink($dir.'/'.$stored);json_out(['error'=>$e->getMessage()],422);}
